(()=>{'use strict';
const $=id=>document.getElementById(id),host=$('cmb-sampling-lab'),P=window.CmbSamplingPhysics,motion=matchMedia('(prefers-reduced-motion: reduce)');if(!host)return;
let result,plans,yMax,visible=1000,seed=1,run,last=0;const format=x=>x===null?'尚无样本':x.toLocaleString('zh-CN',{maximumFractionDigits:5});
window.BookSources=Object.assign(window.BookSources||{},{'cmb-sampling-lab':{title:'全天功率估计与重复天空抽样',pages:'302–304',pdf:'324–326',section:'MBW §6.7.1 · 新增统计推导',body:'原书的高斯、统计各向同性、全天且无噪声假设给出宇宙方差。此处用2ℓ+1个独立实标准正态变量平方和构造归一化χ²功率估计；密度、等尾分位、无偏样本方差和反复天空抽样是原创教学推导，非实际CMB数据。'}});
function stop(){if(run)cancelAnimationFrame(run.frame);run=null;$('sampling-play').textContent='逐批抽样';$('sampling-play').setAttribute('aria-pressed','false');}
function calculate(){stop();result=P.simulate({ell:+$('sampling-ell').value,count:+$('sampling-count').value,seed,bins:60});visible=result.count;plans=[];for(let n=Math.min(100,result.count);n<result.count;n+=Math.max(1,Math.ceil(result.count/45)))plans.push(n);plans.push(result.count);yMax=Math.max(...result.theory.map(d=>d.y));for(const n of plans)yMax=Math.max(yMax,...P.prefixSummary(result,n).histogram.map(b=>b.density));yMax*=1.12;render();}
function render(){const s=P.prefixSummary(result,visible),selectedBin=+$('sampling-bin').value,p=BookCharts.frame('cmb-sampling-chart',{x:d3.scaleLinear().domain(result.xDomain),y:d3.scaleLinear().domain([0,yMax]),xLabel:'功率估计比 R = Ĉℓ / Cℓ',yLabel:'概率密度 p(R)'}),col=BookTheme.palette(['#e4c389','#7abdc4']);
 p.layer.append('rect').attr('x',p.x(result.sigmaBand.lo)).attr('y',p.m.top).attr('width',p.x(result.sigmaBand.hi)-p.x(result.sigmaBand.lo)).attr('height',p.box.h).attr('fill',col[1]).attr('opacity',.06);
 s.histogram.forEach((b,i)=>p.layer.append('rect').attr('x',p.x(b.lo)).attr('y',p.y(b.density)).attr('width',Math.max(.2,p.x(b.hi)-p.x(b.lo)-.5)).attr('height',p.y(0)-p.y(b.density)).attr('fill',col[0]).attr('opacity',i===selectedBin?.9:.55).attr('stroke',i===selectedBin?col[0]:'none').attr('stroke-width',1));
 p.layer.append('path').datum(result.theory).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',col[1]).attr('stroke-width',2);
 p.layer.append('line').attr('x1',p.x(1)).attr('x2',p.x(1)).attr('y1',p.y(0)).attr('y2',p.m.top).attr('stroke',col[1]).attr('stroke-dasharray','3 5');
 // Only the continuous theory is registered as a curve. Histogram bars are bins, not connected values.
 BookCharts.setSeries(p.node,[{label:'χ²理论概率密度',data:result.theory}]);p.node.dataset.visibleCount=visible;p.node.dataset.histogramArea=s.histogramArea;
 const bin=s.histogram[selectedBin];$('sampling-bin-value').textContent=String(selectedBin+1)+'/60';$('sampling-bin-result').textContent=`选中箱：${format(bin.lo)} ≤ R ${selectedBin===59?'≤':'<'} ${format(bin.hi)}；${bin.count}片天空，箱内频率 ${format(100*bin.count/visible)}%，密度 ${format(bin.density)}；理论密度在箱中心为 ${format(P.distribution(result.ell).pdf(bin.center))}。柱高×箱宽 = ${format(bin.density*(bin.hi-bin.lo))}。`;$('sampling-ell-value').textContent=result.ell;$('sampling-count-value').textContent=result.count;$('sampling-nu').textContent=result.nu;$('sampling-mean').textContent=format(s.sampleMean);$('sampling-variance').textContent=format(s.sampleVariance);$('sampling-sd').textContent=format(result.theoreticalSD);$('sampling-coverage').textContent=format(result.sigmaBandCoverage*100)+'%';$('sampling-interval').textContent='['+format(result.central68Interval.lo)+', '+format(result.central68Interval.hi)+']';
 $('sampling-result').textContent=`种子 ${seed} · 已显示 ${visible}/${result.count} 片假想天空。直方图面积 ${format(s.histogramArea)}；柱高是密度，箱内概率为柱高乘箱宽。理论均值固定为1，单片天空理论方差为 ${format(result.theoreticalVariance)}。阴影是均值±σ；低多极时它不是68%等尾区间。更多天空只改善抽样近似，不会降低单片天空的宇宙方差。图域按整批样本和所有计划批次固定；域外理论尾概率 ${format(result.domainTailProbability*100)}%。`;
 document.dispatchEvent(new CustomEvent('lab:render',{detail:{id:host.id}}));}
for(const id of ['sampling-ell','sampling-count'])$(id).addEventListener('input',calculate);
$('sampling-bin').addEventListener('input',render);
$('sampling-resample').onclick=()=>{seed=seed%9999+1;calculate();};$('sampling-reset').onclick=()=>{$('sampling-ell').value=2;$('sampling-count').value=1000;seed=1;calculate();};
$('sampling-play').onclick=()=>{if(run){stop();return;}if(motion.matches){visible=result.count;render();return;}const started=performance.now();run={frame:0};$('sampling-play').textContent='暂停抽样';$('sampling-play').setAttribute('aria-pressed','true');last=-1;const tick=now=>{if(document.hidden||motion.matches||!host.closest('.reader-slide')?.classList.contains('is-active')){stop();return;}const j=Math.min(plans.length-1,Math.floor((now-started)/6000*plans.length));if(j!==last){visible=plans[j];render();last=j;}if(j===plans.length-1)stop();else run.frame=requestAnimationFrame(tick);};run.frame=requestAnimationFrame(tick);};
$('sampling-question').onclick=()=>window.showTutor(`第6章新增全天高斯天空抽样：ℓ=${result.ell}，自由度ν=${result.nu}，N=${result.count}，种子=${seed}。理论方差2/ν=${result.theoreticalVariance}。请推导χ²密度，解释均值±σ覆盖率${result.sigmaBandCoverage}为何不同于中心68%等尾区间，并区分单片天空宇宙方差和样本均值标准误。`);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});motion.addEventListener('change',()=>{if(motion.matches){stop();visible=result.count;render();}});document.addEventListener('reader:pagechange',()=>{if(!host.closest('.reader-slide')?.classList.contains('is-active'))stop();else render();});let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(host.getBoundingClientRect().width)render();},120);});calculate();
})();
